import type { DisplayPlacement } from './asset-pack';
import { ClipTimeline, type FrameAction } from './clip-timeline';
import scripts from '../data/timeline-scripts.json';
const actions = scripts as Record<number, Record<number, FrameAction>>;

export interface ClipSource {
  spriteInfo(id: number): { frameCount: number } | undefined;
  displayList(id: number, age: number): DisplayPlacement[];
}
export interface ClipChild {
  placement: DisplayPlacement;
  clip: SwfClip;
  born: number;
}

/** A retained MovieClip tree shared by painting and geometric contact; no DOM or Pixi dependency. */
export class SwfClip {
  age = 0;
  placements: DisplayPlacement[] = [];
  readonly children = new Map<number, ClipChild>();
  private timeline: ClipTimeline | null;
  constructor(
    readonly id: number,
    private source: ClipSource,
    private random: () => number = Math.random,
    private depth = 0,
  ) {
    const sprite = source.spriteInfo(id);
    this.timeline =
      sprite && depth < 24 ? new ClipTimeline(sprite.frameCount, actions[id], random) : null;
  }
  get frame() {
    return this.timeline?.frame ?? 1;
  }
  /** Constructor goto takes effect before the first retained frame-script pose. */
  start(frame = 1, playing = true, y = 0) {
    if (this.age) return;
    this.age = 1;
    this.timeline?.goto(frame, playing, y);
    this.sync();
  }
  advance(age: number, y = 0) {
    const target = Math.max(1, Math.floor(age));
    if (!this.timeline) {
      this.age = target;
      return;
    }
    while (this.age < target) {
      this.age++;
      this.timeline.tick(y);
      this.sync();
    }
  }
  gotoAndPlay(frame: number, y = 0) {
    if (!this.timeline) return;
    this.timeline.goto(frame, true, y);
    this.sync();
  }
  play() {
    this.timeline?.play();
  }
  gotoAndStop(frame: number, y = 0) {
    if (!this.timeline) return;
    this.timeline.goto(frame, false, y);
    this.sync();
  }
  private sync() {
    const placements = this.source.displayList(this.id, this.frame),
      active = new Set(placements.map((p) => p.depth));
    this.placements = placements;
    for (const depth of this.children.keys()) if (!active.has(depth)) this.children.delete(depth);
    for (const placement of placements) {
      let child = this.children.get(placement.depth);
      if (
        !child ||
        child.clip.id !== placement.charId ||
        child.placement.bornFrame !== placement.bornFrame
      ) {
        child = {
          placement,
          clip: new SwfClip(placement.charId, this.source, this.random, this.depth + 1),
          born: this.age,
        };
        this.children.set(placement.depth, child);
      }
      child.placement = placement;
      child.clip.advance(this.age - child.born + 1, placement.matrix.ty / 20);
    }
  }
}
import { CREDITS } from '../core/credits-screen';
import type { Bounds, Raster } from './asset-pack';

/** Numerical text positions with system glyphs and procedural shapes; no supplied artwork. */
export function mockCreditsLeaf(id: number, bounds: Bounds): Raster {
  const canvas = document.createElement('canvas');
  const b = {
    x: bounds.x - 2,
    y: bounds.y - 2,
    width: bounds.width + 4,
    height: bounds.height + 4,
  };
  canvas.width = Math.ceil(b.width * 2);
  canvas.height = Math.ceil(b.height * 2);
  const ctx = canvas.getContext('2d', { willReadFrequently: true })!;
  ctx.scale(2, 2);
  ctx.translate(-b.x, -b.y);
  const text = CREDITS.texts.find((t) => t.id === id);
  if (text) {
    const m = text.matrix;
    ctx.transform(m.a, m.b, m.c, m.d, m.tx / 20, m.ty / 20);
    for (const glyph of text.glyphs) {
      ctx.font = `${glyph.italic ? 'italic' : 'normal'} ${glyph.font === 'Billo' ? '900' : glyph.bold ? 'bold' : 'normal'} ${glyph.size}px Arial, sans-serif`;
      ctx.fillStyle = `rgba(${glyph.color.slice(0, 3).join(',')},${(glyph.color[3] ?? 255) / 255})`;
      ctx.fillText(glyph.text, glyph.x, glyph.y);
    }
  } else if (id === 572 || id === 574) {
    // Source572/574 are white ellipse fills at38/255 and56/255 opacity.
    ctx.fillStyle = `rgba(255,255,255,${(id === 572 ? 38 : 56) / 255})`;
    ctx.beginPath();
    ctx.ellipse(
      bounds.x + bounds.width / 2,
      bounds.y + bounds.height / 2,
      bounds.width / 2,
      bounds.height / 2,
      0,
      0,
      Math.PI * 2,
    );
    ctx.fill();
  } else if (id === 587) {
    // The source embeds a bitmap logo; the fallback supplies a simple letter badge.
    ctx.fillStyle = '#3b5998';
    ctx.fillRect(0, -15, 30, 30);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 30px Arial, sans-serif';
    ctx.fillText('f', 11, 14);
  }
  //434 is a transparent link target;589 is part of the native logo's erase treatment.
  return {
    ...b,
    canvas,
    resolution: 2,
    pixels: ctx.getImageData(0, 0, canvas.width, canvas.height).data,
    url: canvas.toDataURL('image/png'),
  };
}
